#include "engine/ai_controller.hpp"
#include "engine/editor.hpp"
#include "engine/editor_play.hpp"
#include <iostream>
using namespace engine;
namespace {
int failures=0;void check(bool b,const char* s){if(!b){++failures;std::cerr<<"FAIL: "<<s<<'\n';}}
template<class F>bool rejects(F fn){try{fn();return false;}catch(const std::exception&){return true;}}
std::shared_ptr<const StateMachineDefinition> graph(bool cycle=true){StateMachineData d;d.states={{0,"Move","move",{0,0}},{1,"Idle","idle",{300,0}}};if(cycle)d.transitions={{0,0,1,"always",.2},{1,1,0,"always",.2}};return StateMachineDefinition::create(std::move(d));}
CharacterMotorComponent& motor(Actor& a){CharacterMotorSettings s;s.collisionAware=false;return a.addComponent<CharacterMotorComponent>("Motor",s);}
void runtime(){Scene scene;auto& a=scene.spawn("Agent");auto& m=motor(a);auto settings=AiControllerSettings::defaults(graph(),*AiBindingRegistry::builtins());auto& ai=a.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);
    check(a.transform.position.x>.09f&&ai.status()==StateMachineStatus::Running,"Controller executes before an earlier-inserted free motor");scene.fixedUpdate(.1);check(ai.currentState()==1&&m.movementCommand().velocity.x==0&&ai.transitions().size()==1,"Transition exits clear movement and record history");
    const auto p=a.transform.position.x;ai.enabled=false;scene.fixedUpdate(.1);check(ai.status()==StateMachineStatus::Stopped&&a.transform.position.x==p,"Disable stops persistent commands");ai.enabled=true;scene.fixedUpdate(.1);check(ai.status()==StateMachineStatus::Stopped,"Re-enable requires explicit restart");ai.restart();scene.fixedUpdate(.1);check(a.transform.position.x>p,"Explicit restart starts a fresh agent instance");
    auto bad=settings;bad.states[0].parameters["velocity"]=true;check(rejects([&]{ai.configure(bad);})&&ai.status()==StateMachineStatus::Running,"Wrong parameter type rejects without interrupting valid runtime");bad=settings;bad.states[0].key="missing";check(rejects([&]{ai.configure(bad);}),"Unregistered behavior rejects");
    for(int i=0;i<200;++i)scene.fixedUpdate(.1);check(ai.transitions().size()==32,"Live transition history stays bounded");
    auto& b=scene.spawn("Second");motor(b);auto& second=b.addComponent<AiControllerComponent>("AI",settings);scene.fixedUpdate(.1);check(second.transitions().empty()&&ai.transitions().size()==32,"Instances own separate timers and transition logs");
    ai.destroy();scene.fixedUpdate(.1);check(m.movementCommand().velocity.x==0,"Deferred controller removal stops its motor");
}
void persistence(){Scene scene;auto& a=scene.spawn("Agent");motor(a);auto s=AiControllerSettings::defaults(graph(false),*AiBindingRegistry::builtins());auto& ai=a.addComponent<AiControllerComponent>("AI",s);scene.synchronize();auto id=ai.savedId();auto codecs=aiControllerCodecs();const auto before=SceneArchive::save(scene,{}, {},{}, {},codecs);auto doc=SceneArchive::load(before,{},codecs);auto* restored=dynamic_cast<AiControllerComponent*>(doc.scene->findSavedNode(id));check(restored&&restored->status()==StateMachineStatus::Idle,"Scene codec restores configuration with fresh runtime");check(SceneArchive::save(*doc.scene,{}, {},{}, {},codecs)==before,"Controller scene archive roundtrip retains canonical assignment/configuration");check(rejects([&]{SceneArchive::load(before);}),"Unknown custom codecs reject rather than silently dropping AI");
    EditorPlaySession play;play.start(scene,{}, {},codecs);auto* live=dynamic_cast<AiControllerComponent*>(play.scene()->findSavedNode(id));check(live&&live!=&ai,"Play recreates controller with fresh scene handles");play.advance(0);play.advance(.1);check(live->status()==StateMachineStatus::Running&&ai.status()==StateMachineStatus::Idle,"Only Play instance advances");play.stop();check(SceneArchive::save(scene,{}, {},{}, {},codecs)==before,"Stop preserves source configuration and bytes");
    auto nearGraph=graph(false)->data();nearGraph.transitions={{0,0,1,"near",0}};s=AiControllerSettings::defaults(StateMachineDefinition::create(nearGraph),*AiBindingRegistry::builtins());s.conditions["near"].parameters["target"]=a.savedId();ai.configure(s);auto good=SceneArchive::save(scene,{}, {},{}, {},codecs);auto reloaded=SceneArchive::load(good,{},codecs);reloaded.scene->fixedUpdate(.1);check(dynamic_cast<AiControllerComponent*>(reloaded.scene->findSavedNode(id))->currentState()==1,"Saved actor references resolve in reconstructed scene");
    s.conditions["near"].parameters["target"]=std::string("missing-actor");check(rejects([&]{ai.configure(s);}),"Missing target rejects without partial configuration");
}
void editor(){Scene scene;auto& actor=scene.spawn("Editable agent");auto id=actor.savedId();EditorSession edit(scene);edit.select(id);auto settings=AiControllerSettings::defaults(graph(),*AiBindingRegistry::builtins());check(rejects([&]{edit.setAiController(settings);})&&!actor.hasComponent<AiControllerComponent>()&&edit.undoCount()==0,"Missing motor assignment fails atomically without history");motor(actor);scene.synchronize();check(edit.setAiController(settings)&&actor.hasComponent<AiControllerComponent>(),"Actor assignment creates controller through editor history");check(edit.undo()&&!actor.hasComponent<AiControllerComponent>()&&edit.redo(),"Undo/redo recreates exact controller assignment");auto* ai=edit.selectedAiController();auto next=settings;next.states[0].parameters["velocity"]=Vec3{2,0,0};check(edit.setAiController(next)&&std::get<Vec3>(ai->settings().states.at(0).parameters.at("velocity")).x==2,"Configuration edits publish through scene history");check(edit.undo()&&std::get<Vec3>(ai->settings().states.at(0).parameters.at("velocity")).x==1,"Undo restores previous typed parameters");
    auto bytes=AiControllerArchive::save(settings);check(AiControllerArchive::save(AiControllerArchive::load(bytes,*AiBindingRegistry::builtins()))==bytes,"Controller payload roundtrip is exact");check(rejects([&]{AiControllerArchive::load(bytes+"garbage",*AiBindingRegistry::builtins());}),"Malformed controller payload rejects");
}
}
int main(){runtime();persistence();editor();if(failures)return 1;std::cout<<"Actor AI controller contracts passed\n";}
